from itertools import product

N = 15
elements = [1, 2, 3]
count = 0

def is_kawaii(sequence):
    N = len(sequence)

    # Check if all elements {1, 2, 3} appear
    if 1 not in sequence or 2 not in sequence or 3 not in sequence:
        return False

    # Find positions (1-based index)
    def find_positions(seq, k):
        positions = [i + 1 for i, x in enumerate(seq) if x == k]
        if not positions:
            return None, None # Should not happen if we check containment first
        return min(positions), max(positions)

    # Constraints for k=2: F_1 < L_2
    F1, L1 = find_positions(sequence, 1)
    F2, L2 = find_positions(sequence, 2)
    F3, L3 = find_positions(sequence, 3)

    # Check k=2 constraint (related to 1 and 2)
    if not (F1 < L2):
        return False

    # Check k=3 constraint (related to 2 and 3)
    if not (F2 < L3):
        return False

    return True

# Generate all sequences of length 15 using {1, 2, 3}
for seq_tuple in product(elements, repeat=N):
    sequence = list(seq_tuple)
    if is_kawaii(sequence):
        count += 1

print(count)
